from taf.ul.ettf.state_machine import machinery
from future.utils import with_metaclass
from abc import ABCMeta, abstractmethod


class MatcherWrapper(with_metaclass(ABCMeta, object)):
    @abstractmethod
    def __call__(self, storage):
        pass


class DefaultWrapper(MatcherWrapper):
    def __init__(self, matcher):
        self.matcher = matcher

    def __call__(self, _):
        return self.matcher


class WithStoredArgument(MatcherWrapper):
    def __init__(self, matcher_factory, *stored_keys):
        self.matcher_factory = matcher_factory
        self.stored_keys = stored_keys

    def __call__(self, storage):
        return self.matcher_factory(*[storage.get(key) for key in self.stored_keys])


AVAILABLE_MATCHER_WRAPERS = [DefaultWrapper, WithStoredArgument]


class Event(machinery.Event):
    def _prepare_matcher(self, matcher):
        if type(matcher) not in AVAILABLE_MATCHER_WRAPERS:
            return DefaultWrapper(matcher)
        return matcher


class State(machinery.State):
    def __init__(self, expectations, storage):
        self.expectations = expectations
        self.storage = storage
        super(State, self).__init__()


class MatcherTags(object):
    EXPECTED = 'expected'
    UNEXPECTED = 'unexpected'


class TaggedMatcher(object):
    def __init__(self, matcher, tags):
        self._matcher = matcher
        self._tags = tags

    def __eq__(self, other):
        if not isinstance(other, TaggedMatcher):
            return False
        return self.matcher == other.matcher and self.tags == other.tags

    @property
    def matcher(self):
        return self._matcher

    @property
    def tags(self):
        return self._tags


class Policy(object):
    tags = []
    matcher_name_tag = ''

    @abstractmethod
    def process(self, matcher):
        pass


class Expected(Policy):
    tags = [MatcherTags.EXPECTED]

    def process(self, matcher):
        return TaggedMatcher(matcher, self.tags)


class Unexpected(Policy):
    tags = [MatcherTags.UNEXPECTED]
    matcher_name_tag = 'U'

    def process(self, matcher):
        return TaggedMatcher(matcher, self.tags)
